import{_ as r,o as t,c as o,a5 as a}from"./chunks/framework.CslsFoWx.js";const m=JSON.parse('{"title":"Borne : numéros courts par le hub, webhook du terminal, expiration — preuve du 11/11/2026","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-11-borne-numeros-expiration.md","filePath":"generated/preuves/2026-11-11-borne-numeros-expiration.md","lastUpdated":null}'),n={name:"preuves/2026-11-11-borne-numeros-expiration.md"};function d(s,e,i,c,l,u){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="borne-numeros-courts-par-le-hub-webhook-du-terminal-expiration-—-preuve-du-11-11-2026" tabindex="-1">Borne : numéros courts par le hub, webhook du terminal, expiration — preuve du 11/11/2026 <a class="header-anchor" href="#borne-numeros-courts-par-le-hub-webhook-du-terminal-expiration-—-preuve-du-11-11-2026" aria-label="Permalink to &quot;Borne : numéros courts par le hub, webhook du terminal, expiration — preuve du 11/11/2026&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-11-borne-numeros-expiration</code> · 0 image(s) · 0 trace(s)</p><div><p>Carte Trello « P3 · App kiosque : numéros courts par le hub, webhook TPE, expiration des commandes TPE » (spec 09, RG-KIOSK-05 / -07 / -08 / -10 et §9).</p><h2 id="vraie-stack-utilisee" tabindex="-1">Vraie stack utilisée <a class="header-anchor" href="#vraie-stack-utilisee" aria-label="Permalink to &quot;Vraie stack utilisée&quot;">​</a></h2><ul><li><strong>Serveur</strong> du worktree lancé sur le port 8093, base PostgreSQL séparée, migration <code>V98</code> appliquée (numérotée <code>V99</code> dans la copie de travail) ; back-office servi par <code>ng serve</code> sur le port 4213.</li><li><strong>Commerce fictif</strong> « Le Petit Bistrot (démo) » (<code>help/tools/seed/seed-demo.py</code>), comptes <code>…@vendora.test</code>.</li><li><strong>Borne</strong> : iPad Air 11&quot; (simulateur dédié, portrait), rôle <code>KIOSK</code>, preset au paiement « Sur le TPE », « Expiration du paiement (min) » à 1 pour les scènes d&#39;expiration.</li><li><strong>Caisse</strong> : iPhone 16 (simulateur dédié), rôle <code>REGISTER</code>, élue <strong>hub</strong> du réseau local ; la borne la découvre par mDNS, sans adresse imposée.</li><li><strong>Terminal</strong> : passerelle <strong>simulée</strong> du magasin (webhook signé HMAC-SHA256) ; les paiements sont joués par le simulateur de la page Bornes (<code>POST /api/v1/dev/kiosk-terminal/{storeId}/pay</code>).</li><li>Captures annotées par <code>help/tools/mobile/annotate.py</code> (apps) et <code>help/tools/web/capture.mjs</code> (back-office). Le secret de la passerelle n&#39;apparaît que masqué (« ••••zZSY »).</li></ul><h2 id="captures" tabindex="-1">Captures <a class="header-anchor" href="#captures" aria-label="Permalink to &quot;Captures&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle prouve</th></tr></thead><tbody><tr><td><code>01-ios-borne-repli-sans-hub-KE7-001.webp</code></td><td>Hub injoignable : la borne prend le numéro de repli préfixé par son code, <code>KE7-001</code> (1). La commande n&#39;est pas bloquée.</td></tr><tr><td><code>02-ios-borne-numero-du-hub-K-001.webp</code></td><td>Hub joint : numéro <code>K-001</code> sans préfixe, donné par la caisse hub (1) ; « La borne continue dès que le terminal confirme le paiement » (2), passerelle active.</td></tr><tr><td><code>03-ios-borne-confirmation-automatique-K-001.webp</code></td><td>Après le paiement simulé du bon montant : la borne passe seule à « Merci ! », <code>K-001</code>, « Paiement effectué » (1) — aucun geste du client.</td></tr><tr><td><code>04-ios-borne-numero-suivant-K-002.webp</code></td><td>Commande suivante : <code>K-002</code> (1), les numéros du hub se suivent.</td></tr><tr><td><code>05-ios-borne-merci-K-002.webp</code></td><td><code>K-002</code> confirmée à son tour (1).</td></tr><tr><td><code>06-ios-borne-commande-expiree.webp</code></td><td>Commande restée sans paiement au-delà du délai : retour à l&#39;accueil avec « Commande expirée : le paiement n&#39;a pas été reçu à temps. Recommencez votre commande. » (1).</td></tr><tr><td><code>07-ios-caisse-commande-expiree-K-005.webp</code></td><td>À la caisse, « Commandes kiosque à encaisser » : le numéro saisi répond « K-005 · Commande expirée : le paiement n&#39;a pas été reçu à temps. Le client doit refaire sa commande. » (1) ; la commande n&#39;est plus encaissable. Capture refaite le 11/11 avec le libellé de la caisse, sur le serveur de dev (voir la section Android).</td></tr><tr><td><code>08-ios-caisse-alerte-ecart-terminal.webp</code></td><td>Alerte des responsables : « Paiements de la borne : écart avec le terminal », journée du 10/11/2026 (1).</td></tr><tr><td><code>09-web-rapprochement-sans-ecart.webp</code></td><td>Page Bornes, « Terminal autonome et rapprochement » : journée sans écart, chaque commande confirmée correspond à un paiement du relevé.</td></tr><tr><td><code>10-web-rapprochement-ecarts-du-jour.webp</code></td><td>Les quatre résultats sur une même journée : « Rapprochée », « Montant différent », « Confirmée, absente du relevé » (validation manuelle sans paiement), « Au relevé, sans commande confirmée » ; bandeau « Écart à vérifier » ; simulateur de paiement.</td></tr><tr><td><code>11-web-rapprochement-veille-alerte.webp</code></td><td>Journée terminée du 10/11/2026 en écart (<code>K-017</code> au relevé sans commande) : « Les responsables ont été alertés le 11/11/2026 16:46. »</td></tr><tr><td><code>12-web-commandes-expirees.webp</code></td><td>Service › Additions closes › Kiosque : <code>K-005</code> (1) et <code>KE7-002</code> (2) « Expirée (non payée) ».</td></tr><tr><td><code>13-web-preset-expiration-du-paiement.webp</code></td><td>Réglages › Apparence › Kiosque : « Expiration du paiement (min) » (4), 10 par défaut, proposée quand le paiement est « Sur le TPE ».</td></tr><tr><td><code>14-web-passerelle-du-terminal.webp</code></td><td>Passerelle du terminal active : adresse du webhook, en-tête <code>X-Terminal-Signature</code>, secret masqué, « Désactiver » / « Renouveler le secret ».</td></tr></tbody></table><p>Numéros relevés pendant la séance : <code>K-001</code> à <code>K-005</code> donnés par le hub ; <code>KE7-001</code> et <code>KE7-002</code> en repli, hub coupé.</p><h2 id="defauts-trouves-pendant-la-preuve-corriges-dans-le-lot" tabindex="-1">Défauts trouvés pendant la preuve, corrigés dans le lot <a class="header-anchor" href="#defauts-trouves-pendant-la-preuve-corriges-dans-le-lot" aria-label="Permalink to &quot;Défauts trouvés pendant la preuve, corrigés dans le lot&quot;">​</a></h2><ol><li><strong>Le hub refusait la borne</strong> (« signature LAN invalide ») : le rôle <code>KIOSK</code> n&#39;avait pas le droit de lire la clé du réseau local ni la liste des pairs, ni de déposer sa clé publique. Routes ajoutées à la liste blanche de la borne.</li><li><strong>Un appareil iOS annonçait le hub mais ne découvrait aucun pair</strong> : la découverte Bonjour est maintenant démarrée sur le fil principal.</li><li><strong>L&#39;outbox de la borne ne repartait pas après un push échoué</strong> tant qu&#39;aucun nouvel événement n&#39;arrivait (<code>KE7-002</code> : expiration locale à 16:35 restée en attente, commande expirée par le filet du serveur à 16:40) : chaque pull réussi est maintenant suivi d&#39;un push, sur iOS et sur Android.</li><li><strong>Espace manquant</strong> entre l&#39;en-tête de signature et sa légende dans le bloc de la passerelle. La capture 09, prise avant ce correctif, montre encore « X-Terminal-SignatureHMAC… » collés ; la capture 14 montre l&#39;état corrigé.</li></ol><h2 id="limite-visible-sur-ces-donnees" tabindex="-1">Limite visible sur ces données <a class="header-anchor" href="#limite-visible-sur-ces-donnees" aria-label="Permalink to &quot;Limite visible sur ces données&quot;">​</a></h2><p>Une commande payée au terminal autonome est confirmée (<code>OrderPaymentConfirmed</code>) mais ne crée pas encore de vente : dans Service › Additions closes, elle apparaît « Réglée » avec « Réglé 0,00 € ». C&#39;est le reste documenté dans la spec 09 (« Reste — sortie de stock d&#39;un paiement au terminal autonome »).</p><h2 id="android-memes-scenes-sur-emulateurs-11-11-2026" tabindex="-1">Android : mêmes scènes sur émulateurs (11/11/2026) <a class="header-anchor" href="#android-memes-scenes-sur-emulateurs-11-11-2026" aria-label="Permalink to &quot;Android : mêmes scènes sur émulateurs (11/11/2026)&quot;">​</a></h2><p><strong>Stack</strong> : serveur de dev <code>:8080</code> (code courant, migration <code>V98</code>), commerce fictif « Le Petit Bistrot (démo) » (<code>bistrot.demo+and1108@vendora.test</code>), APK de dev <code>pos.android</code>.</p><ul><li><strong>Borne</strong> : tablette <code>emulator-5554</code> (1600 × 1000, paysage), rôle <code>KIOSK</code>, « Borne entrée (démo) », preset au paiement « Sur le TPE », « Expiration du paiement (min) » à 1.</li><li><strong>Hub</strong> : deux émulateurs Android ne se voient pas en mDNS ; la caisse hub est donc une <strong>caisse iOS</strong> (iPhone, simulateur dédié supprimé à la fin, rôle <code>REGISTER</code>, session ouverte), lancée <strong>avant</strong> la borne. Journal de la borne (<code>adb logcat -s pos.hub</code>) : « pair … (REGISTER) sur 192.168.1.27 », « ÉLECTION (démarrage) → hub = … », « connecté au hub ».</li><li><strong>Caisse Android</strong> : téléphone <code>emulator-5556</code>, rôle <code>REGISTER</code>, pour les scènes 21 et 22.</li><li><strong>Terminal</strong> : passerelle <strong>simulée</strong> du magasin ; paiements joués par <code>POST /api/v1/dev/kiosk-terminal/{storeId}/pay</code>.</li><li>Annotations : <code>help/tools/mobile/scenarios/android-borne-numeros-2026-11-11.json</code>.</li></ul><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle prouve</th></tr></thead><tbody><tr><td><code>15-android-borne-repli-sans-hub-K55-001.webp</code></td><td>Aucune caisse hub sur le réseau : la borne prend le numéro de repli préfixé par son code, <code>K55-001</code> (1). La commande n&#39;est pas bloquée.</td></tr><tr><td><code>16-android-borne-numero-du-hub-K-001.webp</code></td><td>Hub joint : numéro <code>K-001</code> sans préfixe, donné par la caisse hub (1) ; « La borne continue dès que le terminal confirme le paiement » (2).</td></tr><tr><td><code>17-android-borne-confirmation-automatique-K-001.webp</code></td><td>Après le paiement simulé de 11,00 € : la borne passe seule à « Merci ! », <code>K-001</code>, « Paiement effectué » (1) — aucun geste du client.</td></tr><tr><td><code>18-android-borne-numero-suivant-K-002.webp</code></td><td>Commande suivante : <code>K-002</code> (1), les numéros du hub se suivent.</td></tr><tr><td><code>19-android-borne-merci-K-002.webp</code></td><td><code>K-002</code> confirmée à son tour (1). Sans imprimante, la borne garde l&#39;écran avec « Imprimante indisponible : notez votre numéro » (2) jusqu&#39;à « J&#39;ai noté mon numéro ».</td></tr><tr><td><code>20-android-borne-commande-expiree.webp</code></td><td>Commande restée sans paiement plus d&#39;une minute : retour à l&#39;accueil avec « Commande expirée : le paiement n&#39;a pas été reçu à temps. Recommencez votre commande. » (1).</td></tr><tr><td><code>21-android-caisse-commande-expiree-K-003.webp</code></td><td>À la caisse Android, « Commandes kiosque à encaisser » : le numéro saisi répond « K-003 · Commande expirée : le paiement n&#39;a pas été reçu à temps. Le client doit refaire sa commande. » (1) ; la commande n&#39;est plus encaissable.</td></tr><tr><td><code>22-android-caisse-alerte-ecart-terminal.webp</code></td><td>Caisse Android, Alertes : « Paiements de la borne : écart avec le terminal », journée du 10/11/2026, un paiement de 12,50 EUR au relevé sans commande confirmée (1).</td></tr></tbody></table><p>Numéros relevés pendant la séance Android : <code>K55-001</code> en repli (8,00 €, expirée) ; <code>K-001</code>, <code>K-002</code> et <code>K-004</code> payées au terminal simulé (11,00 € chacune) ; <code>K-003</code> et <code>K-005</code> expirées. L&#39;alerte vient d&#39;un paiement simulé <code>K-017</code> de 12,50 € daté du 10/11, sans commande, suivi du rapprochement de la journée du 10/11.</p><p>La capture iOS <code>07-ios-caisse-commande-expiree-K-005.webp</code> a été refaite pendant cette séance sur la caisse iOS hub (numéro <code>K-005</code> de la séance Android).</p><p><strong>Constats sur Android pendant la séance</strong> (non corrigés ici, signalés à l&#39;intégrateur) :</p><ul><li>le titre « Payez 11,00 € sur le terminal à côté de la borne » passe sur deux lignes à 1600 px de large (une seule avec 8,00 €) : capture 16 ;</li><li>sur l&#39;accueil, le chevron de défilement chevauche le titre de la bannière « Formule midi 19,90 € » : capture 20 ;</li><li>Alertes : l&#39;en-tête affiche « 0 à traiter au back-office » alors que deux alertes sont listées : capture 22.</li></ul><p>Après la séance : preset remis à son réglage d&#39;origine (<code>PAY_AT_COUNTER</code>, expiration 10 min) ; passerelle simulée désactivée ; borne, caisse iOS et caisse téléphone de la séance révoquées ; tablette et téléphone rendus à leur rôle d&#39;origine.</p></div>',3)])])}const b=r(n,[["render",d]]);export{m as __pageData,b as default};
